static internal boolean checkIfPricingAttributesAreMatched(
    Common _journalTransaction,
    TAMRebateQueryBuilder _rebateQueryBuilder,        
    TAMRebateDate _rebateDate,
    TAMRebateTable _rebateTable)
{
    str tableName = tableId2Name(_rebateQueryBuilder.transTable());
    InventTransId inventTransId = _journalTransaction.(fieldName2Id(tableName2Id(tableName), 'InventTransId'));
    SalesTable salesTable = SalesTable::find(_journalTransaction.(fieldName2Id(tableName2Id(tableName), 'SalesId')));

    if (salesTable.RecId == 0)
    {
        return false;
    }

    int priority = 0;

    GUPMatchingEntityRebate matchEntityRebate = new GUPMatchingEntityRebate();
    CLRObject rebateEntities = GUPMatchingEntityHelper::createCLRList(matchEntityRebate);

    if (TAMRebateParameters::find().EnablePriceAttributeCombinationPriority)
    {
        date transDate;

        if (_journalTransaction is SalesLine)
        {
            SalesLine salesLine = _journalTransaction as SalesLine;
            transDate = DateTimeUtil::date(salesLine.CreatedDateTime);
        }
        else if (_journalTransaction is CustPackingSlipTrans)
        {
            CustPackingSlipTrans packingSlipTrans = _journalTransaction as CustPackingSlipTrans;
            transDate = packingSlipTrans.DeliveryDate;
        }
        else if (_journalTransaction is CustInvoiceTrans)
        {
            CustInvoiceTrans invoiceTrans = _journalTransaction as CustInvoiceTrans;
            transDate = invoiceTrans.InvoiceDate;
        }

        TAMRebateTable  rebateTable;
        TAMRebateDate   rebateDate;
        GUPPriceComponentCodePriceAttributeGroupCombination combination;

        while select rebateDate
            where rebateDate.RebateFromDate <= transDate && rebateDate.RebateToDate >= transDate
                join rebateTable
                    where rebateDate.RebateId == rebateTable.RebateId && rebateTable.RebateDeal == _rebateTable.RebateDeal
                join PriceComponentCodeName from combination
                    where rebateTable.PriceComponentCombination == combination.RecId
                        && rebateTable.RebateCompanyId == combination.DataAreaId
                        && combination.PriceComponentCodeName == _rebateTable.getPriceComponentCodeName()
        {
            matchEntityRebate = new GUPMatchingEntityRebate();
            priority = rebateTable.getPriority();
            matchEntityRebate.init(rebateTable, rebateDate, priority);
            rebateEntities.add(matchEntityRebate);
        }
    }
    else
    {
        matchEntityRebate.init(_rebateTable, _rebateDate, priority);
        rebateEntities.add(matchEntityRebate);
    }


    CLRObject salesLineIdSet = GUPMatchingEntityHelper::createCLRStringSet();
    salesLineIdSet.add(inventTransId);

    Microsoft.Dynamics.Commerce.Runtime.DataModel.SalesTransaction salesTransaction = RetailPricingEngineHelper::getSalesTransactionFromOrder(salesTable);
    salesTransaction.SalesId = salesTable.SalesId;

    Microsoft.Dynamics.Commerce.Runtime.DataModel.UnifiedPricingParameter unifiedPricingParameter = new Microsoft.Dynamics.Commerce.Runtime.DataModel.UnifiedPricingParameter();

    unifiedPricingParameter.ShouldProcessMatchingInPriorityMode = TAMRebateParameters::find().EnablePriceAttributeCombinationPriority;

    var result = Microsoft.Dynamics.Commerce.Runtime.Services.PricingEngine.AttributePricingPropertiesMatcher::GetMasterDataMatchedByTransaction(
        salesTransaction,
        GUPMatchingEntityHelper::initializeDataAcessor(salesTable.SalesId),
        unifiedPricingParameter,
        rebateEntities,
        salesLineIdSet);

    var listEnumerator = result.get_Item(inventTransId).GetEnumerator();

    if (!listEnumerator.moveNext() || !listEnumerator.get_Current())
    {
        return false;
    }
    else if (TAMRebateParameters::find().EnablePriceAttributeCombinationPriority)
    {
        GUPMatchingEntityRebate matchedRebateEntity = listEnumerator.get_Current();
        return str2Int64(matchedRebateEntity.id) == _rebateDate.RecId;
    }

    return true;
}

static internal boolean checkIfRecordLinkedWithPriceTree(
    Common _journalTransaction,
    TAMRebateQueryBuilder _rebateQueryBuilder,
    TAMRebateTable _rebateTable)
{
    if (GUPParameters::find().EnablePriceTree)
    {
        str tableName = tableId2Name(_rebateQueryBuilder.transTable());
        SalesTable salesTable = SalesTable::find(_journalTransaction.(fieldName2Id(tableName2Id(tableName), 'SalesId')));

        GUPPricingAttributeGroupCombinationName name = _rebateTable.getPriceComponentCodeName();
        SetEnumerator enumerator = GUPPricingTree::getComponentCodeNamesLinkedWithPriceTreeFromSalesId(salesTable.SalesId).getEnumerator();

        while (enumerator.moveNext())
        {
            if (strCmp(name, enumerator.current()) == 0)
            {
                return true;
            }
        }
        return false;
    }
    else
    {
        return true;
    }
}
